Rules.InvariantScript:
Set(
    gblEPAOptions,
    Table(
        { Value: "", Score: Blank() }, // blank default line
        { Value: "Level 1: Limited Participation", Score: 1 },
        { Value: "Level 2: Direct Supervision",   Score: 2 },
        { Value: "Level 3: Indirect Supervision", Score: 3 },
        { Value: "Level 4: Practice Ready",       Score: 4 }
    )
);

// ScreenFeedback.OnVisible
Refresh(VIR_RealTime_FeedBack); // ensure we have the latest

Set(
    varNextSerial,
    Coalesce(
        First(
            SortByColumns(VIR_RealTime_FeedBack, "ID", SortOrder.Descending)
        ).ID,
        0
    ) + 1
);

// Decide mode strictly from incoming selRecord
Set(varSourceGallery, Coalesce(sourceGallery, varSourceGallery));
Set(varSourceRecord, Coalesce(selRecord, varSourceRecord));
Set(varNavMode, Lower(Coalesce(navMode, varNavMode)));

If(varNavMode = "new",
    NewForm(frmFeedback),
    EditForm(frmFeedback)
);

Set(varSelRecord, Self.LastSubmit);

Navigate(
    DetailScreen,
    ScreenTransition.None,
    {
        selRecord: varSelRecord,
        sourceGallery: varSourceGallery
    }
);

// Serial DataCard.Default (if bound to Eval_Serial_No) or a Label.Text
"Serial ID: " & If(
    frmFeedback.Mode = FormMode.New,
    Text(varNextSerial - 117),
    Text(ThisItem.ID - 117) // or ThisItem.Eval_Serial_No if you’re persisting it
)
